import React from 'react';

// Presentation only: callers supply values, validation errors, and file handling.
const PersonalInfoStep = ({ formData, setFormData, errors = {}, onCVChange }) => {
  const handleInputChange = ({ target: { name, value } }) => {
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const field = (name, label, { type = 'text', hint, optional = false, ...props } = {}) => (
    <div className="form-group">
      <label className="form-label" htmlFor={name}>
        {label} {optional && <span className="optional-label">Optional</span>}
      </label>
      <input
        id={name}
        name={name}
        type={type}
        value={formData[name] || ''}
        onChange={handleInputChange}
        className="form-input"
        aria-required={!optional}
        aria-invalid={!!errors[name]}
        aria-describedby={errors[name] ? `${name}-error` : hint ? `${name}-hint` : undefined}
        {...props}
      />
      {hint && <p className="field-hint" id={`${name}-hint`}>{hint}</p>}
      {errors[name] && <p className="form-error" id={`${name}-error`}>{errors[name]}</p>}
    </div>
  );

  return (
    <>
      <nav className="section-nav" aria-label="Form sections">
        <a href="#about-you"><span>01</span> About you</a>
        <a href="#contact-details"><span>02</span> Contact</a>
        <a href="#your-background"><span>03</span> Background</a>
      </nav>

      <section className="profile-section" id="about-you" aria-labelledby="about-title">
        <div className="section-heading">
          <span className="section-number" aria-hidden="true">01</span>
          <div><h2 id="about-title">About you</h2><p>Start with the essentials.</p></div>
        </div>
        <div className="field-grid">
          {field('firstName', 'First name', { autoComplete: 'given-name', placeholder: 'First name' })}
          {field('lastName', 'Last name', { autoComplete: 'family-name', placeholder: 'Last name' })}
          {field('dateOfBirth', 'Date of birth', { type: 'date', autoComplete: 'bday', optional: true })}
          <div className="form-group">
            <label className="form-label" htmlFor="gender">Gender <span className="optional-label">Optional</span></label>
            <select id="gender" name="gender" value={formData.gender || ''} onChange={handleInputChange} className="form-input">
              <option value="">Select an option</option>
              <option value="female">Female</option>
              <option value="male">Male</option>
              <option value="non-binary">Non-binary</option>
              <option value="self-described">Self-described</option>
              <option value="prefer-not-to-say">Prefer not to say</option>
            </select>
          </div>
          {field('nationality', 'Nationality', { placeholder: 'Your nationality', hint: 'You may include more than one nationality.' })}
          {field('preferredLanguage', 'Preferred language', { placeholder: 'e.g. English', autoComplete: 'language' })}
        </div>
      </section>

      <section className="profile-section" id="contact-details" aria-labelledby="contact-title">
        <div className="section-heading">
          <span className="section-number" aria-hidden="true">02</span>
          <div><h2 id="contact-title">Contact details</h2><p>How can we reach you?</p></div>
        </div>
        {field('phone', 'Phone number', { type: 'tel', autoComplete: 'tel', placeholder: '+1 555 123 4567', hint: 'Include your country calling code.' })}
        {field('addressLine1', 'Street address', { autoComplete: 'address-line1', placeholder: 'Street name and number' })}
        {field('addressLine2', 'Apartment, suite, etc.', { autoComplete: 'address-line2', optional: true, placeholder: 'Apartment or unit' })}
        <div className="field-grid">
          {field('city', 'City', { autoComplete: 'address-level2' })}
          {field('region', 'State / province / region', { autoComplete: 'address-level1', optional: true })}
          {field('postalCode', 'Postal code', { autoComplete: 'postal-code', optional: true })}
          {field('country', 'Country / territory', { autoComplete: 'country-name' })}
        </div>
      </section>

      <section className="profile-section" id="your-background" aria-labelledby="background-title">
        <div className="section-heading">
          <span className="section-number" aria-hidden="true">03</span>
          <div><h2 id="background-title">Your background</h2><p>Share a little more about your experience.</p></div>
        </div>
        {field('organization', 'University or organization', { autoComplete: 'organization', optional: true, placeholder: 'Where you study or work' })}
        {field('linkedinUrl', 'LinkedIn profile', { type: 'url', optional: true, placeholder: 'https://www.linkedin.com/in/your-name', hint: 'No LinkedIn profile? You can leave this blank.' })}
        <div className="form-group">
          <label className="form-label" htmlFor="cv">CV / résumé</label>
          <div className="cv-upload">
            <div className="upload-symbol" aria-hidden="true">↑</div>
            <div>
              <strong>Choose your CV</strong>
              <p className="field-hint" id="cv-hint">PDF, DOC, or DOCX · Up to 5 MB</p>
              <input id="cv" name="cv" type="file" accept=".pdf,.doc,.docx" onChange={onCVChange} aria-required="true" aria-describedby="cv-hint" />
            </div>
          </div>
          {errors.cv && <p className="form-error" role="alert">{errors.cv}</p>}
        </div>
      </section>

      <aside className="review-note" aria-label="Before submitting">
        <strong>One last look</strong>
        <p>Check your contact details and CV before submitting your information.</p>
      </aside>
    </>
  );
};

export default PersonalInfoStep;
